def b91encode(input_string):
    """Encodes a given string to a Base91 string.

    Args:
        input_string (str): The string to be encoded.

    Returns:
        str: The Base91 encoded string.
    """
    base91_chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!#$%&()*+,./:;<=>?@[]^_`{|}~"'

    def encode_byte(byte):
        if byte == 0:
            return 'y'
        elif byte == 1:
            return 'z'
        else:
            a, b, c = divmod(byte, 91)
            d, e = divmod(b, 91)
            return base91_chars[a] + base91_chars[d] + base91_chars[e]
    input_bytes = input_string.encode('utf-8')
    encoded_parts = [encode_byte(byte) for byte in input_bytes]
    return ''.join(encoded_parts)

