    for i, c in enumerate(B91_CHARS):
        DECODE_TABLE[ord(c)] = i

    decoded = []
    i = 0
    while i < len(strng):
        a = DECODE_TABLE[ord(strng[i])]
        i += 1
        if i < len(strng):
            b = DECODE_TABLE[ord(strng[i])]
            i += 1
            if i < len(strng):
                c = DECODE_TABLE[ord(strng[i])]
                i += 1
                decoded.append((a * 91 * 91 + b * 91 + c) // 256)
                decoded.append((a * 91 * 91 + b * 91 + c) % 256)
            else:
                decoded.append(a * 91 + b)
        else:
            decoded.append(a)

    result = []
    for value in decoded:
        if value < 128:
            result.append(chr(value))
        else:
            result.append(chr((value // 256) % 256))
