    if sum_dig < digs or sum_dig > 9 * digs:
        return []

    numbers = []

    def backtrack(start, current_sum, current_digits):
        if len(current_digits) == digs:
            if current_sum == sum_dig:
                numbers.append(int(''.join(map(str, current_digits))))
            return
        if current_sum > sum_dig:
            return
        for i in range(start, 10):
            if not current_digits or i >= current_digits[-1]:
                backtrack(i, current_sum + i, current_digits + [i])

    backtrack(0, 0, [])

