def parse_poly(poly):
    import re
    from collections import defaultdict

    # Initialize a dictionary to store the coefficients of each monomial
    monomials = defaultdict(int)

    # Split the polynomial into terms
    terms = poly.split('+')
    for term in terms:
        if '-' in term:
            terms.extend(term.split('-'))
            terms.remove(term)

    for term in terms:
        if term:
            if term[0] == '-':
                sign = -1
                term = term[1:]
            else:
                sign = 1

            # Extract the coefficient and the monomial
            match = re.match(r'([+-]?\d*)([a-z]*)', term)
            coeff = int(match.group(1) or 1)
            monomial = match.group(2)

            # Store the coefficient in the dictionary
            monomials[monomial] += sign * coeff

    # Convert the dictionary to a list of tuples and sort it
    sorted_monomials = sorted(monomials.items(), key=lambda x: (len(x[0]), x[0]))

    # Construct the simplified polynomial string
    simplified_poly = []
    for coeff, monomial in sorted_monomials:
        if coeff != 0:
            if coeff == 1:
                if monomial:
                    simplified_poly.append(monomial)
                else:
                    simplified_poly.append('1')
            elif coeff == -1:
                if monomial:
                    simplified_poly.append('-' + monomial)
                else:
                    simplified_poly.append('-1')
            else:
                simplified_poly.append(f'{coeff}{monomial}')

    return '+'.join(simplified_poly)
