def parse_poly(poly):
    import re
    from collections import defaultdict

    # Regular expression to match terms in the polynomial
    term_pattern = re.compile(r'([+-]?\d*)([a-z]+)')

    # Dictionary to store the coefficients of each monomial
    monomials = defaultdict(int)

    # Split the polynomial into terms and parse each term
    for term in poly.split('+'):
        for sub_term in term.split('-'):
            if sub_term:
                coeff, monomial = term_pattern.match(sub_term).groups()
                coeff = int(coeff) if coeff else 1
                monomials[monomial] += coeff

    # Convert the dictionary to a list of tuples and sort it
    sorted_monomials = sorted(monomials.items(), key=lambda x: (len(x[0]), x[0]))

    # Construct the simplified polynomial string
    simplified_poly = []
    for coeff, monomial in sorted_monomials:
        if coeff != 0:
            if simplified_poly and coeff > 0:
                simplified_poly.append('+')
            simplified_poly.append(f'{coeff}{monomial}')

    return ''.join(simplified_poly)
