def parse_poly(poly):
    import re
    from collections import defaultdict

    # Split the polynomial into terms
    terms = re.split(r'([+-])', poly)
    terms = [t.strip() for t in terms if t.strip()]

    # Dictionary to hold the coefficients of each monomial
    coefficients = defaultdict(int)

    for term in terms:
        if term:
            sign = 1 if term[0] != '-' else -1
            if term[0] in '+-':
                term = term[1:]
            if 'x' not in term:
                coefficients[''] += sign * int(term)
            else:
                monomial = re.sub(r'(\d+)', r'\1x', term)
                coefficients[monomial] += sign * int(re.search(r'(\d+)', term).group(1))

    # Sort the monomials by the number of variables and lexicographically
    sorted_monomials = sorted(coefficients.keys(), key=lambda x: (len(x), x))

    # Construct the simplified polynomial
    simplified_poly = []
    for monomial in sorted_monomials:
        coeff = coefficients[monomial]
        if coeff != 0:
            if monomial:
                simplified_poly.append(f"{coeff}{monomial}")
            else:
                simplified_poly.append(str(coeff))

    # Join the terms with a '+' and handle the leading '+' sign
    result = ''.join(simplified_poly)
    if result.startswith('+'):
        result = result[1:]

    return result
